def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("action", choices=["attach-one"])
    parser.add_argument("directory", type=Path)
    parser.add_argument("--node", help="attach-one: a worker lane of the run, or a reviewer node (review, or review-<id>)")
    args = parser.parse_args()
    directory = args.directory.resolve()
    try:
        sessions = InteractiveSessions(directory, timeout=45)
        if sessions.plan.get("mode") != "interactive":
            parser.error("Not an interactive run; prepare a new run instead of converting print-mode sessions")
        if not args.node or not sys.stdin.isatty():
            parser.error("attach-one requires --node and an interactive terminal")
        if args.node not in sessions.workers and args.node not in review_nodes(sessions.plan):
            parser.error(f"--node must be a lane of this run ({', '.join(sessions.workers)}) or {', '.join(review_nodes(sessions.plan))}")
        receipt = read_json(directory / f"{args.node}.interactive.json")
        if receipt["plan_digest"] != plan_digest(sessions.plan):
            raise RuntimeError("Plan changed; cannot attach")
        attach_one(sessions, args.node)
    except KeyboardInterrupt:
        parser.exit(130, f"\nattach-one interrupted; the {args.node} session keeps running (only the controller stops it).\n")
    except (RuntimeError, ValueError, OSError, subprocess.SubprocessError) as error:
        parser.exit(1, f"Blocked: {error}\nSession/worktree state retained at {directory}; no automatic stop or relaunch.\n")


if __name__ == "__main__":
    main()

    if (self.directory / "terminals.json").exists() and os.environ.get("HERDR_ENV") == "1":
        # The pane is a convenience for the operator; its absence never fails the review. The
        # session is launched by now, so a Ctrl-C here is recorded, then propagated as an
        # interruption (the review node keeps the running session), never as a launch failure.
        try:
            attach_reviewer_panel(self.sessions)
            self.event(REVIEW, "running", f"Reviewer {reviewer_id} pane attached")
        except BaseException as error:
            self.event(REVIEW, "running", f"Reviewer {reviewer_id} pane not attached: {str(error) or type(error).__name__}")
            if not isinstance(error, Exception):
                raise
    return receipt

def reconcile_reviewer(self, reviewer_id: str = DEFAULT_REVIEWER) -> dict:
    """Bind the session an interrupted reviewer launch produced; nothing is launched."""
    node = review_node(reviewer_id)
    path = self.directory / f"{node}.interactive.json"
    if not path.exists():
        raise RuntimeError(f"No durable launch intent for reviewer {reviewer_id}; cannot reconcile without potentially launching a new reviewer")
    self.event(REVIEW, "running", f"Reconciling the interrupted launch of reviewer {reviewer_id}; nothing is relaunched")
    try:
        receipt = self.sessions.reconcile(node, path, read_json(path))
    except Exception as error:
        self.event(REVIEW, "blocked", f"Reviewer {reviewer_id}: {error}")
        raise
    self.event(REVIEW, "interactive", f"Reviewer {reviewer_id} session {receipt['session_id']} reconciled; awaiting {node}.completion.json")
    return receipt

def stop_session(self, node: str) -> None:
    """Persist native identity before stopping. Never signal guessed/reused PIDs."""
    marker = self.directory / f"{node}.stop.json"
    if marker.exists():
        intent = read_json(marker)
    else:
        row = self.sessions.locate(node, self.sessions.inventory())
        if row is None:
            raise RuntimeError(f"{node} session missing before stop; reconcile before continuing")
        intent = {"background_id": row["id"], "session_id": row["sessionId"], "pid": row["pid"], "stopped": False}
        save_json(marker, intent)
    if not intent["stopped"]:
        rows = self.sessions.inventory()
        matching = [row for row in rows if row.get("sessionId") == intent["session_id"] and row.get("pid")]
        if matching:
            row = self.sessions.locate(node, rows)
            if row is None or row["id"] != intent["background_id"] or row["pid"] != intent["pid"]:
                raise RuntimeError(f"Native {node} session identity changed after stop intent; reconcile manually")
            result = subprocess.run([self.sessions.executable, "stop", intent["background_id"]], capture_output=True, text=True, timeout=20)
            if result.returncode != 0:
                raise RuntimeError(f"Stop failed for {node}; inspect native session before retrying")
        # Recover stop-before-receipt without issuing another stop command.
        rows = self.sessions.inventory()
        if any(row.get("sessionId") == intent["session_id"] and row.get("pid") for row in rows) or pid_alive(intent["pid"]):
            raise RuntimeError(f"{node} termination is not established; retry after reconciliation")
        intent["stopped"] = True
        save_json(marker, intent)

def stop_workers(self):
    for node in self.workers:
        self.stop_session(node)
    stopped_ids = {read_json(self.directory / f"{node}.stop.json")["session_id"] for node in self.workers}
    if any(row.get("sessionId") in stopped_ids and row.get("pid") for row in self.sessions.inventory()):
        raise RuntimeError("A stopped worker was restarted; reconcile before snapshot capture")
    self.event("freeze", "stopped", f"Native workers stopped before snapshot capture: {', '.join(self.workers)}")

def stop_reviewer(self, reviewer_id: str = DEFAULT_REVIEWER):
    self.stop_session(review_node(reviewer_id))
    self.event(REVIEW, "stopped", f"Reviewer {reviewer_id} session stopped; its transcript stays resumable")

def freeze(self) -> dict:
    record = self.directory / "snapshots.json"
    if record.exists():
        return read_json(record)
    handoffs = {}
    for node in self.workers:
        handoff_path = self.directory / f"{node}.handoff.json"
        if not handoff_path.exists():
            raise ValueError(f"Missing {node} handoff: summary and open_assumptions are required")
        handoff = read_json(handoff_path)
        if set(handoff) != {"summary", "open_assumptions"} or not isinstance(handoff["summary"], str) or not handoff["summary"].strip() or not isinstance(handoff["open_assumptions"], list) or any(not isinstance(item, str) for item in handoff["open_assumptions"]):
            raise ValueError("Malformed worker handoff")
        handoffs[node] = handoff
    self.stop_workers()
    # Ownership is enforced from the full declared policy: an excluded lane's paths are off-limits to every selected lane.
    excluded_paths = [(other, safe_path(prefix)) for other in self.excluded for prefix in self.worker_policy(other)["owned_paths"]]
    snapshots = {}
    for node in self.workers:
        worker = self.worker_policy(node)
        cwd = Path(self.plan["nodes"][node]["worktree"])
        if git(cwd, "rev-parse", "HEAD") != self.plan["base_commit"]:
            raise ValueError("Worker changed HEAD; reconcile commits rather than silently accepting them")
        changed = changed_files(cwd, self.plan["base_commit"])
        for name in changed:
            safe_path(name)
            for other, prefix in excluded_paths:
                if owns(name, prefix):
                    raise ValueError(f"Ownership violation: {node} edited {name}, owned by excluded lane {other}")
            if not any(owns(name, safe_path(prefix)) for prefix in worker["owned_paths"]):
                raise ValueError(f"{node} edited unowned path: {name}")
            if (cwd / name).is_symlink():
                raise ValueError("Symlink changes require manual review before snapshot")
        index = self.directory / f"{node}.snapshot-index"

def read_completion(runtime, node: str) -> dict:
    item = read_signal(runtime, node)
    if item["status"] == "blocked":
        raise RuntimeError(f"Worker {node} explicitly blocked: {item['summary']}")
    if item["status"] == "question":
        raise RuntimeError(f"Worker {node} asked a question that is not recorded yet: {item['question']}")
    return {"summary": item["summary"], "open_assumptions": item["open_assumptions"]}


def lanes(runtime) -> list[str]:
    """The run's selected lanes, from the runtime when it resolved them or from its plan."""
    return list(getattr(runtime, "workers", None) or plan_workers(runtime.plan))


def wait_handoffs(runtime, *, clock=time.time, sleep=time.sleep) -> None:
    """Idle alone never means completion. Deadlines survive controller restart.

    A 1.1.0 `question` completion pauses only that lane's deadline (persisted in `<node>.deadline.json`) until the
    operator answers, with `workflow answer` or by typing in the pane; the other lanes keep running.
    """
    from .guardrails import PANE_ANSWER, deadline_extension, load_questions, record_answer, record_question, waiting_question
    validate_automatic(runtime.plan)
    workers = lanes(runtime)
    if any((runtime.directory / f"{node}.stop.json").exists() for node in workers):
        # Recover a controller crash after durable handoffs/stop intent, before snapshot.
        for node in workers:
            if read_completion(runtime, node) != read_json(runtime.directory / f"{node}.handoff.json"):
                raise RuntimeError("Handoff changed after stop intent")
        return
    attention: set[str] = set()
    # Answers recorded before this controller started need no second event.
    answered = {(node, entry["n"]) for node in workers for entry in load_questions(runtime.directory, node) if entry["answer"] is not None}
    while True:
        rows = runtime.sessions.inventory()
        handoffs = {}
        for node in workers:
            receipt = read_json(runtime.directory / f"{node}.interactive.json")
            started = datetime.fromisoformat(receipt["launch_requested_at"]).timestamp()
            extension = deadline_extension(runtime.directory, node)  # None while a question waits: that lane has no running deadline.
            if extension is not None and clock() >= started + runtime.plan["automatic"]["worker_timeout_seconds"] + extension:
                raise RuntimeError(f"Worker {node} deadline exhausted; no automatic relaunch")
            row = runtime.sessions.locate(node, rows)
            if row is None:
                raise RuntimeError("Native worker missing; reconciliation required")
            if row["state"] == "working" and waiting_question(runtime.directory, node):
                # The operator typed the answer in the pane: the worker is working again, so its deadline runs again.
                record_answer(runtime.directory, node, PANE_ANSWER, clock)
            for entry in load_questions(runtime.directory, node):
                if entry["answer"] is not None and (node, entry["n"]) not in answered:
                    answered.add((node, entry["n"]))
                    runtime.event(node, "interactive", f"Worker {node} question {entry['n']} answered; its deadline runs again")
            if row["state"] == "blocked" and node not in attention:
                # A native session reports `blocked` when its turn ended needing a human: a question,
                # a permission prompt or a refusal the harness could not continue past. That is not a
                # failure of the lane, and the other lanes keep working. The operator may answer in the
                # pane; the worker deadline bounds the wait. No billing/provider fallback.
                attention.add(node)
                runtime.event(node, "interactive", f"Worker {node} needs attention in its pane (native state blocked); "
                                                   "waiting until its deadline")
            raise RuntimeError(f"Reviewer {reviewer_id} needs reconciliation; no automatic relaunch")
        if partial or not status.get("session_id"):
            try:
                bound = runtime.reconcile_reviewer(reviewer_id)
            except Exception as error:
                status.update(status="needs_reconciliation", error=str(error))
                combined.update(status="needs_reconciliation", error=str(error))
                state.save()
                raise
            status.update(session_id=bound["session_id"], background_id=bound.get("background_id"), status="running")
            status.pop("error", None)
            state.save()
    combined["status"] = "running"
    combined.pop("error", None)
    state.save()


def reviewer_stopped(runtime, reviewer_id: str = DEFAULT_REVIEWER) -> bool:
    """Only a confirmed stop intent counts; an absent or unconfirmed one means the stop is still owed."""
    marker = runtime.directory / f"{review_node(reviewer_id)}.stop.json"
    return marker.exists() and read_json(marker).get("stopped") is True


def stop_reviewers(runtime, ids: list[str]) -> list[str]:
    """Stop every reviewer, continuing past failures; the unconfirmed ones are returned."""
    errors = []
    for reviewer_id in ids:
        try:
            runtime.stop_reviewer(reviewer_id)
        except Exception as error:
            errors.append(f"{reviewer_id}: {error}")
    return errors


